ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS source_provider uuid REFERENCES public.service_providers(id), ADD COLUMN IF NOT EXISTS manual_control boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS public.service_snapshots (id bigserial PRIMARY KEY, label text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.service_snapshots TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.service_snapshots_id_seq TO service_role;
ALTER TABLE public.service_snapshots ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.enforce_category_source() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _p uuid; BEGIN IF NEW.provider_id IS NULL THEN RETURN NEW; END IF; SELECT source_provider INTO _p FROM public.categories WHERE id=NEW.category_id; IF _p IS NOT NULL AND _p<>NEW.provider_id THEN NEW.active:=false; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS enforce_category_source ON public.services;
CREATE TRIGGER enforce_category_source BEFORE INSERT ON public.services FOR EACH ROW EXECUTE FUNCTION public.enforce_category_source();
CREATE OR REPLACE FUNCTION public.validate_service_source_order() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _s public.services; _manual boolean; BEGIN SELECT * INTO _s FROM public.services WHERE id=NEW.service_id; SELECT manual_control INTO _manual FROM public.categories WHERE id=_s.category_id; IF NOT public.service_source_enabled(_s.provider_id) OR NOT _s.provider_available THEN RAISE EXCEPTION 'SERVICE_UNAVAILABLE'; END IF; IF coalesce(_manual,false) THEN NEW.dispatch_state:='manual'; RETURN NEW; END IF; IF _s.provider_id IS NOT NULL AND NOT _s.provider_order_supported THEN RAISE EXCEPTION 'SPECIAL_INPUT_REQUIRED'; END IF; NEW.provider_id:=_s.provider_id; NEW.provider_service_id:=_s.provider_service_id; IF _s.provider_id IS NOT NULL THEN NEW.dispatch_state:='queued'; END IF; RETURN NEW; END $$;